{
  "technical_and_design_decisions": [
    "All new functions will be implemented in Go within the existing fabric-config library codebase, following established patterns for config manipulation (e.g., using protobuf and the configtx package).",
    "For the CLI tool (U6), we will use the Cobra/Viper libraries for command-line parsing and configuration, and reuse the fabric-config library for config updates.",
    "Existing functions like GetConfiguration/SetConfiguration and GetMSP/SetMSP will be preserved; new individual setter functions will be added alongside them.",
    "For U2, the unsigned envelope will be created by omitting the signing step and returning a cb.ConfigUpdateEnvelope directly.",
    "For U3 and U4, removal functions will modify the channel group and enforce that no update is allowed to set the legacy fields.",
    "For U5, add/remove consenter functions will match on host, port, client TLS cert, and server TLS cert for removal.",
    "For U6, the tool will support dry-run by printing the computed config update to stdout without submitting it, and will stack multiple operations in a single batch.",
    "For U7 and U8, functions will persist existing values for other fields when updating individual ones (e.g., SetMaxMessageCount keeps other BatchSize values)."
  ],
  "assumptions": [
    "The developer has prior experience with Hyperledger Fabric, Go, and the fabric-config library, and does not require ramp-up time.",
    "Existing test infrastructure (unit tests, linters, CI) is in place; new tests will be added within each activity.",
    "All examples will be updated as specified, but writing extensive documentation (user guides) beyond examples is not included.",
    "The CLI tool does not need to support all possible connection profile fields; only those required per the specification.",
    "Effort estimates include coding, unit testing, and updating examples for the respective user story.",
    "No deployment or packaging (e.g., Docker images, release scripts) is required; only source code changes.",
    "The codebase is under active development; no conflicts or merge overhead are considered."
  ],
  "activities": [
    {
      "activity_id": "U1",
      "activity_name": "Add New Consortium API",
      "activity_description": "Implement AddNewConsortium function in fabric-config library to add a new consortium to the consortiums group, including handling the case where no orgs are added, and updating examples.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U2",
      "activity_name": "Unsigned ConfigUpdateEnvelope Function",
      "activity_description": "Implement a function that returns a cb.ConfigUpdateEnvelope without requiring signing identities, enabling later signing via peer channel commands.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U3",
      "activity_name": "RemoveLegacyOrdererAddresses Function",
      "activity_description": "Implement RemoveLegacyOrdererAddresses to remove top-level orderer addresses from channel config, and prevent setting of OrdererAddresses field. New genesis blocks must be created without the field.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U4",
      "activity_name": "RemoveKafkaBrokers Function",
      "activity_description": "Implement a function to remove the KafkaBrokers section from config, similar to RemoveLegacyOrdererAddresses. Add/improve example for Kafka to EtcdRaft migration.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U5",
      "activity_name": "Add/Remove Consenter API for EtcdRaft",
      "activity_description": "Implement AddConsenter and RemoveConsenter functions for etcdraft orderer configuration, matching host, port, and both TLS certs for removal.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U6",
      "activity_name": "CLI Tool for Bulk Operations on Multiple Channels",
      "activity_description": "Develop a CLI tool that consumes the fabric-config library to perform bulk operations (update MSP, add/remove consenters, add/remove anchor peers, TLS cert updates, etc.) on a list of channels. Supports dry-run mode, error messages for unsupported operations, stacking multiple operations, connection profile, signing identities, and fetching/submitting config transactions via peer discovery.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "U7",
      "activity_name": "Individual Orderer Config Field Setters",
      "activity_description": "Add new API functions to OrdererGroup for setting individual fields: SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetConsensusState, and additional EtcdRaft metadata functions (e.g., AddConsenter/RemoveConsenter already covered in U5, but also other individual metadata value setters). Keep existing SetConfiguration/GetConfiguration.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U8",
      "activity_name": "Individual MSP Field Setters for Org Groups",
      "activity_description": "Add new API functions to OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup for individual MSP field updates: AddRootCert/RemoveRootCert, AddIntermediateCert/RemoveIntermediateCert, AddAdminCert/RemoveAdminCert, AddCRL/RemoveCRL, AddOUIdentifier/RemoveOUIdentifier, SetCryptoConfig, AddTLSRootCert/RemoveTLSRootCert, AddTLSIntermediateCert/RemoveTLSIntermediateCert, SetClient/Peer/Admin/OrdererOUIdentifier, EnableNodeOUs/DisableNodeOUs. Perform necessary certificate validation. Keep existing GetMSP/SetMSP.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 38
  }
}

